/**
 * Monitoring Dashboard API - Health Report Validation
 * Secure endpoint to receive and validate health check reports
 * 
 * Usage: POST http://localhost:3003/api/health-report
 * Body: { health report JSON from healthcheck.sh }
 */

const express = require('express');
const crypto = require('crypto');
const router = express.Router();

// Load server credentials (from secure storage, not from .env!)
// These should match what's in the client's .env.test file
const serverCredentials = {
  DATABASE_URL: 'postgresql://localhost:5432/testdb',
  API_KEY: 'sk-test-1234567890abcdefghijk',
  SECRET_TOKEN: 'secret_xyz_987654321',
  MONITORING_SECRET: 'mon_sec_abcd1234'
};

/**
 * Generate credential hash (same algorithm as client)
 * This allows server to verify client has correct credentials
 */
function generateCredentialHash(credentials) {
  const credentialKeys = ['KEY', 'TOKEN', 'SECRET', 'PASSWORD', 'CREDENTIAL'];

  // Extract credential values that match patterns
  let credentialString = '';
  for (const [key, value] of Object.entries(credentials)) {
    if (credentialKeys.some(pattern => key.includes(pattern))) {
      credentialString += value + ':';
    }
  }

  // Generate SHA256 hash
  return crypto
    .createHash('sha256')
    .update(credentialString)
    .digest('hex');
}

/**
 * Validate health report from client
 * 
 * @param {Object} report - Health report JSON from healthcheck.sh
 * @returns {Object} { valid: boolean, error?: string, message?: string }
 */
function validateHealthReport(report) {
  // 1. Validate report structure
  if (!report || typeof report !== 'object') {
    return { valid: false, error: 'Invalid report format' };
  }

  if (!report.credentials || !report.credentials.hash) {
    return { valid: false, error: 'Missing credential hash' };
  }

  if (!report.authentication || !report.authentication.token) {
    return { valid: false, error: 'Missing authentication token' };
  }

  if (!report.timestamp) {
    return { valid: false, error: 'Missing timestamp' };
  }

  // 2. Validate credential hash
  const expectedHash = generateCredentialHash(serverCredentials);
  const receivedHash = report.credentials.hash;

  if (receivedHash !== expectedHash) {
    return {
      valid: false,
      error: 'Credential validation failed - hash mismatch',
      severity: 'CRITICAL'
    };
  }

  // 3. Validate timestamp is recent (within 5 minutes)
  const reportTime = new Date(report.timestamp).getTime();
  const now = Date.now();
  const ageMs = now - reportTime;
  const maxAgeMs = 5 * 60 * 1000; // 5 minutes

  if (isNaN(reportTime)) {
    return { valid: false, error: 'Invalid timestamp format' };
  }

  if (ageMs > maxAgeMs) {
    return {
      valid: false,
      error: `Report expired - age ${Math.floor(ageMs / 1000)}s exceeds max ${Math.floor(maxAgeMs / 1000)}s`,
      severity: 'WARNING'
    };
  }

  if (ageMs < -60000) { // Report from future? (more than 1 min)
    return {
      valid: false,
      error: 'Report timestamp from future',
      severity: 'WARNING'
    };
  }

  // 4. All validations passed
  return {
    valid: true,
    message: `Health report validated successfully (age: ${Math.floor(ageMs / 1000)}s)`,
    ageSeconds: Math.floor(ageMs / 1000),
    hash: receivedHash
  };
}

/**
 * POST /api/health-report
 * Receive and validate health check reports
 */
router.post('/api/health-report', async (req, res) => {
  try {
    const report = req.body;

    // Log incoming report (safe - no credentials)
    console.log('[HEALTH] Received report from', report.hostname);
    console.log('[HEALTH] Status:', report.status);
    console.log('[HEALTH] Services:', report.services.healthy, '/', report.services.total, 'healthy');

    // Validate the report
    const validation = validateHealthReport(report);

    if (!validation.valid) {
      console.error('[HEALTH] Validation failed:', validation.error);

      // Return error response
      const statusCode = validation.severity === 'CRITICAL' ? 401 : 400;
      return res.status(statusCode).json({
        status: 'error',
        error: validation.error,
        severity: validation.severity || 'ERROR'
      });
    }

    console.log('[HEALTH] Validation passed:', validation.message);

    // Store the health report in database
    try {
      await storeHealthReport(report, validation);
    } catch (dbError) {
      console.error('[HEALTH] Database error:', dbError.message);
      // Don't fail the request if database has issues
      // Just log and continue
    }

    // Update service status in dashboard
    try {
      await updateDashboard(report);
    } catch (dashboardError) {
      console.error('[HEALTH] Dashboard update error:', dashboardError.message);
    }

    // Send success response
    return res.status(200).json({
      status: 'ok',
      message: validation.message,
      reportAge: validation.ageSeconds,
      credentialHash: validation.hash.substring(0, 8) + '...' // Only show first 8 chars
    });

  } catch (error) {
    console.error('[HEALTH] Unexpected error:', error.message);
    return res.status(500).json({
      status: 'error',
      error: 'Internal server error',
      message: error.message
    });
  }
});

/**
 * Store health report in database
 */
async function storeHealthReport(report, validation) {
  // Example: MongoDB storage
  const healthReportModel = require('../models/HealthReport');

  await healthReportModel.create({
    hostname: report.hostname,
    timestamp: new Date(report.timestamp),
    status: report.status,
    services: report.services,
    credentialCount: report.credentials.count,
    credentialHashSample: report.credentials.hash.substring(0, 8),
    ageSeconds: validation.ageSeconds,
    createdAt: new Date()
  });
}

/**
 * Update monitoring dashboard
 */
async function updateDashboard(report) {
  // Example: Update Redis cache
  const redis = require('redis');
  const client = redis.createClient();

  await client.set(
    `health:${report.hostname}:latest`,
    JSON.stringify({
      timestamp: report.timestamp,
      status: report.status,
      services: report.services
    }),
    'EX',
    600 // Expire in 10 minutes
  );
}

/**
 * GET /api/health-status
 * Dashboard endpoint to view current health status
 */
router.get('/api/health-status', async (req, res) => {
  try {
    // Example: Get from cache/database
    const reports = await getLatestReports();

    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      reports: reports
    });
  } catch (error) {
    res.status(500).json({
      status: 'error',
      error: error.message
    });
  }
});

/**
 * Get latest health reports
 */
async function getLatestReports() {
  // Example implementation
  const healthReportModel = require('../models/HealthReport');

  return await healthReportModel
    .find()
    .sort({ timestamp: -1 })
    .limit(10);
}

/**
 * Health Check Validation Test
 * For testing/development purposes
 */
if (require.main === module) {
  // Test with sample report
  const sampleReport = {
    hostname: 'server-01',
    timestamp: new Date().toISOString(),
    status: 'healthy',
    services: {
      total: 2,
      healthy: 2,
      unhealthy: 0
    },
    credentials: {
      verified: true,
      count: 3,
      hash: generateCredentialHash(serverCredentials)
    },
    authentication: {
      token: 'test_token',
      timestamp: new Date().toISOString()
    }
  };

  console.log('\n=== HEALTH CHECK VALIDATION TEST ===\n');
  console.log('Sample Report:');
  console.log(JSON.stringify(sampleReport, null, 2));

  console.log('\n--- Validation Result ---');
  const result = validateHealthReport(sampleReport);
  console.log(JSON.stringify(result, null, 2));

  if (result.valid) {
    console.log('\n✅ Report is VALID\n');
  } else {
    console.log('\n❌ Report is INVALID\n');
  }
}

module.exports = router;

